constexpr size_t budget=64u*1024u*1024u;
constexpr auto bonuses=std::array{&AuraBonuses::movement,&AuraBonuses::attackSpeed,&AuraBonuses::armor,&AuraBonuses::armorPercent,&AuraBonuses::health,&AuraBonuses::healthPercent,&AuraBonuses::mana,&AuraBonuses::manaPercent,&AuraBonuses::meleeDamage,&AuraBonuses::rangedDamage,&AuraBonuses::meleeFlat,&AuraBonuses::rangedFlat,&AuraBonuses::vampiric,&AuraBonuses::thorns,&AuraBonuses::thornsFlat};
void real(SnapshotWriter& out,float value){if(!std::isfinite(value))throw std::runtime_error("Invalid aura real");out.u32(std::bit_cast<std::uint32_t>(value));}
float real(Binary& in){auto value=std::bit_cast<float>(in.u32());if(!std::isfinite(value))throw std::runtime_error("Invalid aura real");return value;}
void time(SnapshotWriter& out,double value){if(!std::isfinite(value))throw std::runtime_error("Invalid aura time");out.u64(std::bit_cast<std::uint64_t>(value));}
double time(Binary& in){auto value=std::bit_cast<double>(snapshotU64(in));if(!std::isfinite(value))throw std::runtime_error("Invalid aura time");return value;}
bool flag(Binary& in){auto value=in.u32();if(value>1)throw std::runtime_error("Invalid aura flag");return value!=0;}
std::string fingerprint(const PassiveInfo& value){SnapshotWriter out(16u*1024u*1024u);writePassiveSnapshot(out,value);return sha256(out.finish());}
struct SavedAuras {std::uint32_t id=0,type=0,owner=0;std::map<std::uint32_t,UnitAura> auras;std::map<std::pair<std::string,std::string>,std::uint32_t> visuals;std::vector<std::uint32_t> spikes;std::uint32_t spikeType=0;AuraBonuses aura;};
