Bytes ScriptSession::encodeUnitAuras(const jass::StableHandleMap& encodeHandle) const {
    if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || (!units_.empty() && !encodeHandle))throw std::runtime_error("Aura snapshot requires a quiescent local session and handle mapping");if(units_.size()>65536 || auraEmitters_.size()>65536)throw std::runtime_error("Aura count exceeds budget");SnapshotWriter out(budget-64);out.u32(tag("SAUR"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));out.u32(auraTicks_);out.size(units_.size());std::map<std::pair<unsigned,std::uint32_t>,std::uint32_t> forward,reverse;auto handle=[&](std::uint32_t id,unsigned mask){if(!id){out.u32(0);return;}if(id<handleBase || id-handleBase>=objects_.size())throw std::runtime_error("Invalid aura handle");auto kind=objects_[id-handleBase].kind;unsigned tag=kind==NativeKind::Unit?1:kind==NativeKind::Effect?2:0;if(!tag || !(mask&(1u<<tag)))throw std::runtime_error("Invalid aura handle type");auto stable=encodeHandle(tag==1?"unit":"effect",id);auto a=std::pair{tag,id},b=std::pair{tag,stable};if(!stable || (forward.contains(a) && forward.at(a)!=stable) || (reverse.contains(b) && reverse.at(b)!=id))throw std::runtime_error("Invalid aura handle mapping");forward[a]=stable;reverse[b]=id;out.u32(tag);out.u32(stable);};auto effects=[&](const auto& values){if(values.size()>8192)throw std::runtime_error("Aura effects exceed budget");out.size(values.size());for(auto id:values)handle(id,4);};for(auto& [id,u]:units_){if(!u || !alive(id,NativeKind::Unit) || u->removing || u->handle!=id || u->owner>=16 || u->auras.size()>65536 || u->auraVisuals.size()>8192)throw std::runtime_error("Invalid aura unit");handle(id,2);out.u32(u->type);out.u32(u->owner);for(auto field:bonuses)real(out,u->aura.*field);out.size(u->auras.size());for(auto& [key,entry]:u->auras){if(!entry.definition || !entry.definition->aura)throw std::runtime_error("Invalid aura definition");out.u32(key);out.u32(entry.definition->ability);out.u32(entry.definition->level);out.text(fingerprint(*entry.definition),64);handle(entry.source,2);time(out,entry.remaining);real(out,entry.amountBonus);out.u32(entry.positive?1:0);}out.size(u->auraVisuals.size());for(auto& [key,effect]:u->auraVisuals){out.text(key.first,65536);out.text(key.second,65536);handle(effect,4);}effects(u->spikeVisuals);out.u32(u->spikeVisualType);}out.size(auraEmitters_.size());for(auto& [key,entry]:auraEmitters_){handle(key.first,2);out.u32(key.second);out.u32(entry.level);effects(entry.effects);}return sealSnapshot(out.finish(),budget);
}
void ScriptSession::restoreUnitAuras(std::span<const std::uint8_t> bytes,const jass::StableHandleMap& decodeHandle) {
    if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || !unitRecoveryIncomplete_ || !unitCoreFinished_ || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || liveObjects(NativeKind::Event) || !auraEmitters_.empty())throw std::runtime_error("Aura restore requires completed core before events and empty emitters");Binary in(openSnapshot(bytes,budget));in.expect(tag("SAUR"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest())throw std::runtime_error("Aura snapshot map mismatch");if(time(in)!=simulationTime_)throw std::runtime_error("Aura snapshot clock mismatch");auto ticks=in.u32(),count=in.count(4,65536);if(count!=units_.size() || (count && !decodeHandle))throw std::runtime_error("Aura unit count differs");std::map<std::pair<unsigned,std::uint32_t>,std::uint32_t> forward,reverse;auto handle=[&](unsigned mask){auto tag=in.u32();if(!tag)return std::uint32_t(0);if(tag>2 || !(mask&(1u<<tag)))throw std::runtime_error("Invalid aura handle type");auto stable=in.u32();auto& identities=tag==1?unitIdentityHandles_:effectIdentityHandles_;auto id=decodeHandle(tag==1?"unit":"effect",stable);auto kind=tag==1?NativeKind::Unit:NativeKind::Effect;auto a=std::pair{tag,stable},b=std::pair{tag,id};if(!stable || !identities.contains(stable) || identities.at(stable)!=id || id<handleBase || id-handleBase>=objects_.size() || objects_[id-handleBase].kind!=kind || (forward.contains(a) && forward.at(a)!=id) || (reverse.contains(b) && reverse.at(b)!=stable))throw std::runtime_error("Invalid aura handle mapping");forward[a]=id;reverse[b]=stable;return id;};auto effects=[&]{std::vector<std::uint32_t> result;auto size=in.count(4,8192);for(unsigned i=0;i<size;++i)result.push_back(handle(4));return result;};std::vector<SavedAuras> saved;saved.reserve(count);std::set<std::uint32_t> targets;for(unsigned i=0;i<count;++i){SavedAuras v;v.id=handle(2);v.type=in.u32();v.owner=in.u32();if(!v.id || !targets.insert(v.id).second || !alive(v.id,NativeKind::Unit) || !units_.contains(v.id) || units_.at(v.id)->type!=v.type || units_.at(v.id)->owner!=v.owner || !units_.at(v.id)->auras.empty() || !units_.at(v.id)->auraVisuals.empty() || !units_.at(v.id)->spikeVisuals.empty())throw std::runtime_error("Invalid aura unit mapping");for(auto field:bonuses)v.aura.*field=real(in);auto size=in.count(4,65536);for(unsigned n=0;n<size;++n){auto key=in.u32(),ability=in.u32(),level=in.u32();auto digest=snapshotText(in,64);auto& definition=passiveInfo(ability,level);if(!definition.aura || fingerprint(definition)!=digest)throw std::runtime_error("Aura definition differs");UnitAura entry;entry.definition=&definition;entry.source=handle(2);entry.remaining=time(in);entry.amountBonus=real(in);entry.positive=flag(in);if(!v.auras.emplace(key,std::move(entry)).second)throw std::runtime_error("Duplicate aura identity");}auto visuals=in.count(12,8192);for(unsigned n=0;n<visuals;++n){auto model=snapshotText(in,65536),attachment=snapshotText(in,65536);auto effect=handle(4);if(!v.visuals.emplace(std::pair{std::move(model),std::move(attachment)},effect).second)throw std::runtime_error("Duplicate aura visual");}v.spikes=effects();v.spikeType=in.u32();saved.push_back(std::move(v));}std::map<std::pair<std::uint32_t,std::uint32_t>,AuraEmitterVisual> emitters;auto emitterCount=in.count(12,65536);for(unsigned i=0;i<emitterCount;++i){auto unit=handle(2),ability=in.u32();AuraEmitterVisual value;value.level=in.u32();value.effects=effects();if(!emitters.emplace(std::pair{unit,ability},std::move(value)).second)throw std::runtime_error("Duplicate aura emitter");}in.finish();for(auto& v:saved){auto& u=*units_.at(v.id);u.auras=std::move(v.auras);u.auraVisuals=std::move(v.visuals);u.spikeVisuals=std::move(v.spikes);u.spikeVisualType=v.spikeType;u.aura=v.aura;}auraTicks_=ticks;auraEmitters_=std::move(emitters);
}
